<template>
    <HsxDrawer v-model="visible" title="ERP 接入向导" :subtitle="merchantName" size="md" :body-loading="loading" :confirm-loading="busy">
        <el-steps :active="step" finish-status="success" simple class="lead-banner"><el-step title="选 ERP" /><el-step title="填授权" /><el-step title="验证预览" /><el-step title="启用同步" /></el-steps>
        <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="lead-error-banner" />
        <template v-if="!loading">
            <template v-if="step === 0"><p class="lead-muted">先验证新授权，验证失败不会影响原来的接入。当前每个商户保留一个启用连接。</p><div v-for="item in providers" :key="item.key" class="lead-candidate" :class="{ 'is-selected': provider === item.key }" role="radio" :aria-checked="provider === item.key" tabindex="0" @click="choose(item.key)" @keydown.enter.prevent="choose(item.key)"><h4>{{ item.name }}</h4><p class="lead-muted">{{ Array.isArray(item.notes) ? item.notes.join('；') : item.notes || '只读获取库存资料，不修改 ERP 的商品与库存。' }}</p></div><el-empty v-if="!providers.length" description="暂无可用 ERP，请联系管理员确认插件配置" /></template>
            <template v-if="step === 1"><h3>{{ schema?.name }} · 授权信息</h3><el-form label-position="top" class="lead-form" :disabled="busy"><el-form-item v-for="field in schema?.fields || []" :key="field.key" :label="field.label" :required="field.required"><el-input v-model="credentials[field.key]" :type="field.secret ? 'password' : 'text'" :show-password="!!field.secret" :maxlength="field.max_length || 2000" :autocomplete="field.secret ? 'new-password' : 'off'" :placeholder="field.secret && original.provider === provider && original.configured_fields?.includes(field.key) ? '已保存；身份未变时留空保留' : (field.placeholder || `填写${field.label}`)" /><p v-if="field.help" class="lead-muted">{{ field.help }}</p></el-form-item><el-form-item v-for="field in (schema?.scope_fields || []).filter(item => item.required)" :key="field.key" :label="field.label" required><el-input v-model="scope[field.key]" :maxlength="field.max_length || 100" :placeholder="field.placeholder || '按接口要求填写来源范围'" /></el-form-item><el-collapse v-if="schema?.scope_fields?.some(item => !item.required)"><el-collapse-item title="来源范围（按接口要求填写；可自动识别的项目可留空）"><el-form-item v-for="field in (schema.scope_fields || []).filter(item => !item.required)" :key="field.key" :label="field.label" :required="field.required"><el-input v-model="scope[field.key]" :maxlength="field.max_length || 100" :placeholder="field.placeholder || '按 ERP 来源信息填写'" /><p v-if="field.help" class="lead-muted">{{ field.help }}</p></el-form-item></el-collapse-item></el-collapse></el-form><el-alert title="凭据只发送给本插件的安全验证服务，不会下发给商户会员，也不会在页面回显已保存的密钥。" type="info" :closable="false" /></template>
            <template v-if="step === 2"><h3>只读验证结果</h3><el-descriptions :column="1" border><el-descriptions-item label="ERP">{{ schema?.name }}</el-descriptions-item><el-descriptions-item label="来源身份">{{ preview.identity?.name || preview.identity?.tenant_id || preview.identity?.store_id || '已核对授权身份' }}</el-descriptions-item><el-descriptions-item label="首屏商品">{{ preview.first_page_count ?? 0 }} 条{{ preview.has_more ? ' · 还有后续分页' : ' · 首屏分页已结束' }}</el-descriptions-item><el-descriptions-item label="数据边界">首屏条数不是库存总数，更不是已确认可售数量</el-descriptions-item></el-descriptions><el-table v-if="preview.items?.length" :data="preview.items" size="small" style="margin-top: 16px"><el-table-column prop="title" label="首屏商品预览" min-width="180" /><el-table-column prop="brand" label="品牌" width="100" /><el-table-column prop="price" label="快照价格" width="100" /><el-table-column prop="store_id" label="来源门店 ID" min-width="120" /></el-table><el-alert v-if="preview.empty_inventory" title="授权可读取，但没有商品可用于核对来源门店，因此暂不能启用。商户资料已保留，待有库存后重新验证。" type="warning" :closable="false" style="margin-top: 16px" /><el-form v-if="preview.stores?.length" label-position="top" style="margin-top: 20px"><el-form-item label="确认来源门店"><el-select v-model="selectedStore" placeholder="请选择本商户对应的来源门店" style="width: 100%"><el-option v-for="store in preview.stores" :key="store.store_id" :label="`${store.name || '来源门店'} · ${store.store_id}`" :value="String(store.store_id)" /></el-select></el-form-item></el-form><el-alert v-if="preview.requires_store_selection || storeChanged" title="需确认门店范围。选择后会重新进行只读验证；不能跳过范围校验直接启用。" type="warning" :closable="false" /><el-alert v-if="impact.message" :title="impact.message" :type="impact.switching || impact.published_snapshot_will_be_hidden ? 'warning' : 'info'" :closable="false" style="margin-top: 16px" /><el-checkbox v-if="!needsStoreProbe && preview.can_activate !== false" v-model="confirmed" style="margin-top: 18px">我已核对 ERP 及来源门店，确认启用{{ original.connected ? '并替换当前接入' : '' }}</el-checkbox><p class="lead-muted">验证有效期至 {{ time(probeExpires) }}；启用时不再次传送凭据。</p></template>
            <template v-if="step === 3"><el-result icon="success" title="ERP 接入已启用" sub-title="下一步完成首次同步，完整发布库存后才参与库存匹配。" /><el-form label-position="top" class="lead-form"><el-form-item label="自动同步"><el-switch v-model="settings.enabled" /></el-form-item><el-form-item label="同步间隔（分钟）"><el-input-number v-model="settings.interval_minutes" :min="15" :max="1440" :precision="0" /><p class="lead-muted">默认 60 分钟；修改周期不会替你开启牛云服务器计划任务。</p></el-form-item></el-form></template>
        </template>
        <template #footer><div class="lead-actions" style="justify-content: flex-end"><el-button :disabled="busy" @click="visible = false">关闭</el-button><el-button v-if="step > 0 && step < 3" :disabled="busy" @click="step--">上一步</el-button><el-button v-if="step === 0" type="primary" :disabled="!provider || loading" @click="step = 1">填写授权</el-button><el-button v-if="step === 1" type="primary" :loading="busy" @click="probe">只读验证与预览</el-button><el-button v-if="step === 2 && needsStoreProbe" type="primary" :disabled="!selectedStore" :loading="busy" @click="reprobeStore">确认门店并重新验证</el-button><el-button v-if="step === 2 && !needsStoreProbe" type="primary" :disabled="!confirmed || !probeToken || preview.can_activate === false" :loading="busy" @click="activate">确认启用接入</el-button><el-button v-if="step === 3" type="primary" :loading="busy" @click="initialSync">保存周期并开始首次同步</el-button></div></template>
    </HsxDrawer>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import HsxDrawer from '@/addon/hsx_components/components/HsxDrawer/index.vue'
import * as api from '../../api'
import { errorText, time, type Row } from '../../composables/useLeadUi'
const props = defineProps<{ modelValue: boolean, merchantId: number, merchantName?: string }>()
const emit = defineEmits<{ (e: 'update:modelValue', value: boolean): void, (e: 'changed'): void, (e: 'sync', merchantId: number): void }>()
const visible = computed({ get: () => props.modelValue, set: value => emit('update:modelValue', value) })
const step = ref(0), loading = ref(false), busy = ref(false), error = ref(''), providers = ref<Row[]>([]), original = ref<Row>({}), provider = ref(''), credentials = reactive<Row>({}), scope = reactive<Row>({}), preview = ref<Row>({}), impact = ref<Row>({}), selectedStore = ref(''), probeToken = ref(''), probeExpires = ref(0), confirmed = ref(false), verifiedScope = ref('')
const settings = reactive({ enabled: true, interval_minutes: 60 })
const schema = computed(() => providers.value.find(item => item.key === provider.value))
const storeChanged = computed(() => !!selectedStore.value && selectedStore.value !== String(verifiedScope.value || ''))
const needsStoreProbe = computed(() => !!preview.value.requires_store_selection || storeChanged.value)
let sequence = 0
function clearSecrets() { for (const key of Object.keys(credentials)) delete credentials[key] }
function choose(key: string) { if (provider.value === key) return; provider.value = key; clearSecrets(); Object.keys(scope).forEach(key => delete scope[key]); if (original.value.provider === key) { Object.assign(credentials, original.value.credentials || {}); Object.assign(scope, original.value.scope || {}) }; probeToken.value = ''; confirmed.value = false }
async function load() { const token = ++sequence; step.value = 0; loading.value = true; error.value = ''; clearSecrets(); provider.value = ''; original.value = {}; try { const [list, connection] = await Promise.all([api.getProviders(), api.getConnection(props.merchantId)]); if (token !== sequence) return; providers.value = list.data.items || []; original.value = connection.data || {}; choose(original.value.provider || providers.value[0]?.key || ''); settings.enabled = original.value.connected ? !!original.value.enabled : true; settings.interval_minutes = Number(original.value.interval_minutes || 60) } catch (cause) { if (token === sequence) error.value = errorText(cause, '接入信息读取失败，请关闭后重试。') } finally { if (token === sequence) loading.value = false } }
async function probe() { if (busy.value || !schema.value) return; for (const field of [...(schema.value.fields || []), ...(schema.value.scope_fields || [])]) { const values = (schema.value.scope_fields || []).includes(field) ? scope : credentials; const configured = field.secret && original.value.provider === provider.value && original.value.configured_fields?.includes(field.key) && (schema.value.fields || []).filter((item: Row) => !item.secret && item.identity).every((item: Row) => String(credentials[item.key] || '') === String(original.value.credentials?.[item.key] || '')); if (field.required && !values[field.key] && !configured) { error.value = `请填写${field.label}`; return } }; busy.value = true; error.value = ''; probeToken.value = ''; confirmed.value = false; const token = sequence; try { const result = await api.probeConnection(props.merchantId, { provider: provider.value, credentials: { ...credentials }, scope: { ...scope } }); if (token !== sequence) return; probeToken.value = result.data.probe_token; probeExpires.value = result.data.expires_at; preview.value = result.data.preview || {}; impact.value = result.data.impact || {}; verifiedScope.value = String(scope.store_id || preview.value.identity?.store_id || (preview.value.stores?.length === 1 ? preview.value.stores[0].store_id : '')); selectedStore.value = verifiedScope.value || (preview.value.stores?.length === 1 ? String(preview.value.stores[0].store_id) : ''); step.value = 2 } catch (cause) { if (token === sequence) error.value = errorText(cause, '验证失败，原接入未更改。') } finally { if (token === sequence) busy.value = false } }
async function reprobeStore() { if (!selectedStore.value) return; scope.store_id = selectedStore.value; await probe() }
async function activate() { if (!confirmed.value || !probeToken.value || needsStoreProbe.value || preview.value.can_activate === false || busy.value) return; busy.value = true; error.value = ''; try { await api.activateConnection(props.merchantId, { probe_token: probeToken.value, ...(scope.store_id ? { store_id: scope.store_id } : {}), confirm_switch: true }); clearSecrets(); probeToken.value = ''; step.value = 3; emit('changed') } catch (cause) { error.value = errorText(cause, '启用未完成，验证可能已过期，请重新验证。') } finally { busy.value = false } }
async function initialSync() { busy.value = true; error.value = ''; try { await api.saveSyncSettings(props.merchantId, { ...settings }); visible.value = false; emit('sync', props.merchantId) } catch (cause) { error.value = errorText(cause, '周期未保存，接入已启用，可稍后在同步设置中处理。') } finally { busy.value = false } }
watch(() => [props.modelValue, props.merchantId], () => { if (visible.value && props.merchantId) void load(); else { sequence++; clearSecrets(); probeToken.value = ''; busy.value = false } }, { immediate: true })
onBeforeUnmount(() => { sequence++; clearSecrets(); probeToken.value = '' })
</script>
